/**
 * Build-only bridge: compiled after the *real* Springdoc document is
 * generated by Gradle and Orval 8 emits its TypeScript client.
 *
 * Never import this module into the Vite app. There is deliberately no fetch,
 * credential, React hook invocation or HTTP endpoint exposed here.
 */
import {
  csrf, consoleLogin, consoleLogout, current, list, find, overview,
  getCsrfUrl, getConsoleLoginUrl, getConsoleLogoutUrl,
} from '../.generated-contract/lanveriq';
import type {
  ConsoleCsrfToken,
  ConsoleLoginBody,
  ConsoleSessionInfo,
  DeviceHealthSummary,
  ScopedDeviceDirectoryPage,
  ScopedMonitoringOverview,
} from '../.generated-contract/model';

// These compile-time assignments prove the generated client is consumable by
// the Web project's real React Query 5 / TypeScript 7 dependency graph.
// Their functions are intentionally never called.
export type GeneratedConsoleContract = {
  csrf: typeof csrf;
  login: typeof consoleLogin;
  logout: typeof consoleLogout;
  session: typeof current;
  deviceList: typeof list;
  deviceDetail: typeof find;
  overview: typeof overview;
  csrfUrl: typeof getCsrfUrl;
  loginUrl: typeof getConsoleLoginUrl;
  logoutUrl: typeof getConsoleLogoutUrl;
  credentials: ConsoleLoginBody;
  csrfToken: ConsoleCsrfToken;
  sessionInfo: ConsoleSessionInfo;
  health: DeviceHealthSummary;
  page: ScopedDeviceDirectoryPage;
  monitoring: ScopedMonitoringOverview;
};

export type LoginMustUseGeneratedFormBody = ConsoleLoginBody extends {
  username: string;
  password: string;
} ? true : never;

export const loginFormShapeSatisfied: LoginMustUseGeneratedFormBody = true;


/**
 * Backend record components are authoritative. A generated model declaring
 * an always-present value optional must fail the Java → Springdoc → Orval →
 * Web type gate before a real console can be connected. No requests run here.
 */
type AllRequired<T, K extends keyof T> =
  false extends { [P in K]: {} extends Pick<T, P> ? false : true }[K]
    ? never
    : true;
type Optional<T, K extends keyof T> =
  {} extends Pick<T, K> ? true : never;

export const healthIdentityIsMandatory: AllRequired<DeviceHealthSummary,
  'device_id' | 'group_id' | 'group_name' | 'label' | 'enrollment_state'> = true;
export const directoryItemsAreMandatory: AllRequired<ScopedDeviceDirectoryPage,
  'items'> = true;
export const monitoringCountsAreMandatory: AllRequired<ScopedMonitoringOverview,
  'as_of' | 'total' | 'online' | 'stale' | 'offline' | 'revoked' | 'pending' | 'retired'> = true;
export const sessionLoginIsMandatory: AllRequired<ConsoleSessionInfo, 'login'> = true;
export const csrfTokenIsMandatory: AllRequired<ConsoleCsrfToken, 'csrfToken'> = true;

// No heartbeat/inventory or further page is legitimate; never fill nulls
// with fabricated activity, counters, identifiers or online state.
export const heartbeatMayBeMissing: Optional<DeviceHealthSummary, 'heartbeat_received_at'> = true;
export const cursorMayBeMissing: Optional<ScopedDeviceDirectoryPage, 'next_cursor'> = true;
